class Solution {
public:
    int findCrossingTime(int n, int k, vector<vector<int>>& time) {
        auto cmp = [&](int a, int b) {
            int ea = time[a][0] + time[a][2], eb = time[b][0] + time[b][2];
            return ea != eb ? ea < eb : a < b;
        };
        priority_queue<int, vector<int>, decltype(cmp)> wl(cmp), wr(cmp);
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> bl, br;
        for (int i = 0; i < k; i++) wl.push(i);
        long long cur = 0; int rem = n, ans = 0;
        while (rem > 0 || !wr.empty() || !br.empty()) {
            while (!bl.empty() && bl.top().first <= cur) { wl.push(bl.top().second); bl.pop(); }
            while (!br.empty() && br.top().first <= cur) { wr.push(br.top().second); br.pop(); }
            if (!wr.empty()) {
                int i = wr.top(); wr.pop();
                cur += time[i][2]; rem--;
                ans = max(ans, (int)cur);
                bl.push({cur + time[i][3], i});
            } else if (rem > 0 && !wl.empty()) {
                int i = wl.top(); wl.pop();
                cur += time[i][0];
                br.push({cur + time[i][1], i});
            } else {
                long long nx = LLONG_MAX;
                if (!br.empty()) nx = br.top().first;
                if (rem > 0 && !bl.empty()) nx = min(nx, bl.top().first);
                cur = nx;
            }
        }
        return ans;
    }
};

