class Solution {
    public int findCrossingTime(int n, int k, int[][] time) {
        java.util.PriorityQueue<Integer> wl = new java.util.PriorityQueue<>((a, b) -> {
            int ea = time[a][0] + time[a][2], eb = time[b][0] + time[b][2];
            return ea != eb ? eb - ea : b - a;
        });
        java.util.PriorityQueue<Integer> wr = new java.util.PriorityQueue<>((a, b) -> {
            int ea = time[a][0] + time[a][2], eb = time[b][0] + time[b][2];
            return ea != eb ? eb - ea : b - a;
        });
        java.util.PriorityQueue<long[]> bl = new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        java.util.PriorityQueue<long[]> br = new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        for (int i = 0; i < k; i++) wl.add(i);
        long cur = 0; int rem = n, ans = 0;
        while (rem > 0 || !wr.isEmpty() || !br.isEmpty()) {
            while (!bl.isEmpty() && bl.peek()[0] <= cur) wl.add((int) bl.poll()[1]);
            while (!br.isEmpty() && br.peek()[0] <= cur) wr.add((int) br.poll()[1]);
            if (!wr.isEmpty()) {
                int i = wr.poll();
                cur += time[i][2]; rem--;
                ans = Math.max(ans, (int) cur);
                bl.add(new long[]{cur + time[i][3], i});
            } else if (rem > 0 && !wl.isEmpty()) {
                int i = wl.poll();
                cur += time[i][0];
                br.add(new long[]{cur + time[i][1], i});
            } else {
                long nx = Long.MAX_VALUE;
                if (!br.isEmpty()) nx = br.peek()[0];
                if (rem > 0 && !bl.isEmpty()) nx = Math.min(nx, bl.peek()[0]);
                cur = nx;
            }
        }
        return ans;
    }
}

