var findCrossingTime = function(n, k, time) {
    const eff = i => time[i][0] + time[i][2];
    const best = q => q.reduce((m, x) => eff(x) !== eff(m) ? (eff(x) > eff(m) ? x : m) : (x < m ? x : m));
    let wl = [], wr = [], bl = [], br = [];
    for (let i = 0; i < k; i++) wl.push(i);
    let cur = 0, rem = n, ans = 0;
    while (rem > 0 || wr.length || br.length) {
        bl = bl.filter(e => { if (e.t <= cur) { wl.push(e.i); return false; } return true; });
        br = br.filter(e => { if (e.t <= cur) { wr.push(e.i); return false; } return true; });
        if (wr.length) {
            const i = best(wr);
            wr.splice(wr.indexOf(i), 1);
            cur += time[i][2]; rem--;
            ans = Math.max(ans, cur);
            bl.push({ t: cur + time[i][3], i });
        } else if (rem > 0 && wl.length) {
            const i = best(wl);
            wl.splice(wl.indexOf(i), 1);
            cur += time[i][0];
            br.push({ t: cur + time[i][1], i });
        } else {
            let nx = Infinity;
            for (const e of br) nx = Math.min(nx, e.t);
            if (rem > 0) for (const e of bl) nx = Math.min(nx, e.t);
            cur = nx;
        }
    }
    return ans;
};
